from pathlib import Path

root=Path(__file__).resolve().parents[2]
base=(root/'public/previews/kho-xe-mau-21.html').read_text(encoding='utf-8')
css=r'''
.demo-gallery{grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;align-content:start;grid-auto-rows:max-content}.group-card{padding:19px 21px 17px;overflow:visible}.group-heading h2{font-size:23px}.group-photo img{height:128px;margin:7px 0 10px}.group-color{font-size:11px;padding-bottom:15px;justify-content:flex-start;gap:12px}.group-stats{display:flex;gap:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:13px 0;margin-bottom:15px}.group-stat{flex:1;border-right:1px solid var(--line);padding-left:17px}.group-stat:first-child{padding-left:0}.group-stat:last-child{border:0}.group-stat strong{display:block;font-size:18px;font-weight:500;color:#314c71;margin-bottom:5px}.group-stat span{color:#8a9db8;font-size:10px;display:flex;align-items:center;gap:5px}.mini-dot{width:5px;height:5px;border-radius:50%;display:inline-block;background:var(--tone)}.group-select{width:100%;border:1px solid #d8e2f0;border-radius:5px;display:flex;align-items:center;justify-content:space-between;padding:11px 13px;color:#245b9e;font-size:12px;background:#fbfcff}.group-select:hover{background:#edf4ff;border-color:#a1bce0}.vin-drawer{width:min(1090px,calc(100vw - 92px))}.drawer-body{display:block;overflow:auto;scrollbar-width:thin}.vin-list{border-right:0;overflow:visible}.vin-detail{padding:19px 26px;overflow:visible}.drawer-body[data-step="list"] .vin-detail{display:none}.drawer-body[data-step="detail"] .vin-list{display:none}.drawer-heading h2{font-size:23px}.drawer-heading{padding:23px 26px}.back-list{font-size:12px;color:#2e65a7;padding:0 0 12px}.back-list[hidden]{display:none}.list-column-head{display:grid;grid-template-columns:minmax(190px,1.7fr) 1fr 1fr minmax(150px,1.1fr) 158px;gap:18px;padding:13px 24px;background:#fbfcfe;color:#8c9eb7;font-size:10px;border-bottom:1px solid var(--line)}.list-column-head span:last-child{text-align:right}.simple-row{display:grid;grid-template-columns:minmax(190px,1.7fr) 1fr 1fr minmax(150px,1.1fr) 158px;gap:18px;align-items:center;padding:17px 24px;border-bottom:1px solid var(--line);font-size:12px;cursor:pointer}.simple-row:hover{background:#f7faff}.simple-row .vin-link{font-family:Consolas,monospace;color:#315a8b;font-size:12px;padding:0;text-align:left;display:block}.simple-row small{display:block;color:#92a3ba;font-size:10px;margin-top:7px;line-height:1.5}.simple-row .status{font-size:11px}.simple-row .row-location{font-size:11px;color:#627d9e}.simple-row .row-holder{font-size:10px;color:#657e9d;line-height:1.6}.simple-row .row-holder small{font-size:10px}.row-actions{display:flex;align-items:center;gap:8px;justify-content:flex-end}.row-actions .btn{font-size:11px;padding:9px 11px}.row-actions .primary{min-width:112px}.more-button{border:1px solid #dfe7f2;border-radius:4px;height:33px;min-width:30px;color:#8299b7;font-size:21px;line-height:20px;display:grid;place-items:center}.more-button:hover,.more-button[aria-expanded="true"]{background:#edf3fd;border-color:#a8bfdc;color:#285e9f}.actions-menu{position:fixed;z-index:45;width:224px;border:1px solid #dce5f2;border-radius:6px;background:white;box-shadow:0 10px 35px #18304f1c;padding:5px}.actions-menu[hidden]{display:none}.actions-menu button{display:block;width:100%;text-align:left;padding:10px 11px;color:#4a678d;font-size:12px;border-radius:3px}.actions-menu button:hover{background:#f0f5fd;color:#215aa2}.actions-menu .menu-title{font-family:Consolas,monospace;font-size:10px;color:#94a5bc;border-bottom:1px solid var(--line);padding:8px 11px 10px;margin-bottom:4px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 32px}.detail-grid .field-row{grid-template-columns:105px minmax(0,1fr);padding:10px 0;font-size:11px;min-height:42px}.detail-grid .copy-value{font-size:11px}.detail-hero{padding-bottom:12px}.detail-hero img{width:155px;height:92px}.detail-actions{position:static;display:flex;justify-content:space-between;align-items:center;margin:0;padding:11px 0;border-bottom:1px solid var(--line)}.detail-actions .helper{font-size:10px;color:#91a4bf}.detail-actions .row-actions .btn{font-size:12px}.detail-section-title{padding:14px 0 12px}.detail-section-title .btn{display:none}.queue-box{margin-top:15px}.drawer-tools .search{max-width:400px}.drawer-bottom{background:#fff}.drawer-heading .heading-controls{display:flex;align-items:center;gap:13px}.step-indicator{font-size:10px;color:#94a5bd;letter-spacing:.1px}.demo-banner{background:#fafbfd;border-color:#e9edf5}.demo-banner span:last-child{color:#93a4ba}.list-summary{padding:15px 24px;color:#92a5bf;font-size:10px}.vin-drawer.detail-view .drawer-tools{display:none}.detail-view .drawer-heading{padding-top:17px;padding-bottom:17px}.detail-grid .field-value{overflow-wrap:anywhere}.demo-head{padding-bottom:19px}.demo-settings .btn{font-size:10px}@media(max-width:1400px){.demo-gallery{grid-template-columns:repeat(3,minmax(0,1fr))}.group-photo img{height:110px}.group-heading h2{font-size:21px}.simple-row,.list-column-head{gap:12px;grid-template-columns:minmax(175px,1.5fr) .8fr .9fr minmax(135px,1fr) 155px}}@media(max-width:1100px){.demo-gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.vin-drawer{width:calc(100vw - 75px)}.simple-row,.list-column-head{gap:11px;grid-template-columns:minmax(165px,1.5fr) .8fr .9fr 150px}.simple-row .row-holder,.list-column-head .holder-head{display:none}.detail-grid{gap:0 20px}.detail-grid .field-row{grid-template-columns:90px minmax(0,1fr)}}@media(max-width:760px){.demo-gallery{grid-template-columns:1fr}.vin-drawer{width:calc(100vw - 15px)}.detail-grid{grid-template-columns:1fr}.simple-row,.list-column-head{grid-template-columns:minmax(155px,1fr) 145px;gap:10px}.simple-row .row-location,.simple-row .row-status,.list-column-head .location-head,.list-column-head .status-head{display:none}.vin-list{max-height:none;flex-shrink:1}.step-indicator{display:none}.vin-detail{padding:16px}.detail-actions .helper{display:none}.drawer-tools{padding:12px}.group-photo img{height:125px}}
'''
js=r'''
let drawerStep='list',menuTrigger=null;
const oldOpenDrawer=openDrawer,oldCloseDrawer=closeDrawer,oldRenderDetail=renderDetail;
const drawer=document.querySelector('.vin-drawer');
const back=document.createElement('button');back.id='back-to-list';back.className='back-list';back.textContent='← Danh sách VIN';back.hidden=true;document.querySelector('.drawer-heading>div').prepend(back);
const menu=document.createElement('div');menu.id='vin-actions-menu';menu.className='actions-menu';menu.hidden=true;menu.setAttribute('role','menu');document.body.append(menu);
function closeMore(returnFocus=false){menu.hidden=true;if(menuTrigger){menuTrigger.setAttribute('aria-expanded','false');if(returnFocus)menuTrigger.focus()}menuTrigger=null}
function choosePrimary(c){if(readonly())return null;const temp=document.createElement('div');temp.innerHTML=primaryActions(c);const allowed=Array.from(temp.querySelectorAll('[data-action]'));return allowed.find(b=>['hold','match','queue','leave'].includes(b.dataset.action))||null}
function actionHTML(c){const primary=choosePrimary(c);return `<div class="row-actions">${readonly()?'<span class="mode-note">Chỉ xem</span>':primary?primary.outerHTML:(!canHold()&&c.status==='Chưa ghép'?'<button class="btn" disabled>Hết lượt giữ xe</button>':'')}<button type="button" class="more-button" data-more-vin="${c.vin}" aria-label="Thao tác khác cho VIN ${c.vin}" aria-haspopup="menu" aria-expanded="false">⋯</button></div>`}
function showMore(c,trigger){if(menuTrigger===trigger&&!menu.hidden){closeMore();return}closeMore();menuTrigger=trigger;trigger.setAttribute('aria-expanded','true');const temp=document.createElement('div');temp.innerHTML=readonly()?'':primaryActions(c);const primary=choosePrimary(c);const actions=[{action:'detail',label:'Xem đầy đủ thông tin'},{action:'logs',label:'Xem nhật ký'}];for(const b of temp.querySelectorAll('[data-action]'))if(!primary||b.dataset.action!==primary.dataset.action)actions.push({action:b.dataset.action,label:b.textContent});if(mode==='admin'){actions.push({action:'edit',label:'Chỉnh sửa thông tin'},{action:'delete',label:'Xóa xe khỏi mẫu'})}if(c.coords)actions.push({action:'map',label:'Xem vị trí GPS'});menu.innerHTML=`<div class="menu-title">${esc(c.vin)}</div>`+actions.map(a=>`<button role="menuitem" data-menu-action="${a.action}" data-vin="${c.vin}">${esc(a.label)}</button>`).join('');menu.hidden=false;const r=trigger.getBoundingClientRect();const h=menu.getBoundingClientRect().height;menu.style.left=Math.max(8,Math.min(r.right-224,innerWidth-232))+'px';menu.style.top=Math.max(8,Math.min(r.bottom+6,innerHeight-h-8))+'px';menu.querySelectorAll('[data-menu-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();const a=b.dataset.menuAction;closeMore();if(a==='detail'||a==='logs'){selectedVIN=c.vin;drawerStep='detail';detailTab=a==='logs'?'logs':'specs';renderDrawer();$('back-to-list').focus()}else if(!readonly()||a==='map')showAction(c,a)});menu.querySelector('button')?.focus()}
function bindMore(root){root.querySelectorAll('[data-more-vin]').forEach(b=>b.onclick=e=>{e.stopPropagation();showMore(getVIN(b.dataset.moreVin),b)})}
renderStock=function(){const visible=filteredStock();$('total-count').textContent=stock.length;$('stock-count').textContent=visible.length+' / '+stock.length+' xe';$('stock-tabs').innerHTML=['','Chưa ghép','Đang giữ','Đã ghép'].map(s=>`<button class="${s===statusChoice?'on':''}" data-stock-status="${s}">${s||'Tất cả xe'}<small>${s?stock.filter(c=>c.status===s).length:stock.length}</small></button>`).join('');const keys=[...new Set(visible.map(c=>c.model+'|'+c.color+'|'+c.interior))];$('stock-gallery').innerHTML=keys.map(key=>{const group=visible.filter(c=>c.model+'|'+c.color+'|'+c.interior===key);const c=group[0];return `<section class="group-card"><div class="group-heading"><h2>${c.model}</h2><small>${group.length} xe</small></div><button class="group-photo" data-open-model="${c.model}" data-group-color="${esc(c.color)}" aria-label="Chọn xe ${c.model}, ${esc(c.color)}"><img src="../pictures/${c.image}.webp" alt="${c.model} ${esc(c.color)}"></button><div class="group-color"><i class="swatch" style="margin:0"></i><span>${esc(c.color)} / ${esc(c.interior)}</span></div><div class="group-stats">${[['Chưa ghép','#23a572'],['Đang giữ','#e9ad29'],['Đã ghép','#3779cc']].map(([s,t])=>`<div class="group-stat"><strong>${group.filter(c=>c.status===s).length}</strong><span><i class="mini-dot" style="--tone:${t}"></i>${s}</span></div>`).join('')}</div><button class="group-select" data-open-model="${c.model}"><span>Chọn xe · ${group.length} VIN</span><span>→</span></button></section>`}).join('')||'<div class="empty-result">Không tìm thấy xe phù hợp.</div>';$('stock-tabs').querySelectorAll('[data-stock-status]').forEach(b=>b.onclick=()=>{statusChoice=b.dataset.stockStatus;renderStock()});$('stock-gallery').querySelectorAll('[data-open-model]').forEach(b=>b.onclick=()=>openDrawer(b.dataset.openModel))};
openDrawer=function(model,vin=''){closeMore();drawerStep=vin?'detail':'list';oldOpenDrawer(model,vin)};
closeDrawer=function(){closeMore();oldCloseDrawer()};
renderDrawer=function(){closeMore();if($('drawer-overlay').hidden)return;drawer.classList.toggle('detail-view',drawerStep==='detail');document.querySelector('.drawer-body').dataset.step=drawerStep;$('back-to-list').hidden=drawerStep!=='detail';const all=stock.filter(c=>c.model===drawerModel);const visible=drawerVehicles();if(!visible.some(c=>c.vin===selectedVIN))selectedVIN=visible[0]?.vin||'';$('drawer-title').textContent=drawerStep==='detail'?'Chi tiết VIN · '+drawerModel:drawerModel+' · Chọn xe';$('drawer-subtitle').textContent=drawerStep==='detail'?selectedVIN:`${all.length} xe · ${all.filter(c=>c.status==='Chưa ghép').length} chưa ghép · ${all.filter(c=>c.status==='Đang giữ').length} đang giữ · ${all.filter(c=>c.status==='Đã ghép').length} đã ghép`;$('drawer-count').textContent=visible.length+' / '+all.length+' xe';$('vin-list').innerHTML=`<div class="list-column-head"><span>Số VIN / Phiên bản</span><span class="status-head">Trạng thái</span><span class="location-head">Kho / Vị trí</span><span class="holder-head">Người giữ / Thời hạn</span><span>Thao tác</span></div>`+visible.map(c=>`<div class="simple-row" data-select-vin="${c.vin}" tabindex="0" role="group" aria-label="Thông tin xe ${c.vin}"><div><button class="vin-link" data-show-vin="${c.vin}">${c.vin}</button><small>${c.version} · ${esc(c.color)} / ${esc(c.interior)}</small></div><div class="row-status"><span class="status" style="--tone:${tone(c.status)}">${c.status}</span>${isMine(c)?'<small>Tôi đang giữ</small>':''}${c.extension?'<small>Chờ duyệt gia hạn</small>':''}</div><div class="row-location">${esc(c.location)}<small>${esc(c.parking)}</small></div><div class="row-holder">${esc(c.holder||'—')}<small>${c.expiry?fmt(c.expiry):'—'}</small></div>${actionHTML(c)}</div>`).join('')+`<div class="list-summary">${visible.length} xe · Bấm VIN để xem đầy đủ thông tin. Thao tác phụ nằm trong nút ⋯.</div>`;$('vin-list').querySelectorAll('[data-select-vin]').forEach(row=>{row.onclick=e=>{if(e.target.closest('[data-action],[data-more-vin]'))return;selectedVIN=row.dataset.selectVin;drawerStep='detail';detailTab='specs';renderDrawer();$('back-to-list').focus();document.querySelector('.drawer-body').scrollTop=0};row.onkeydown=e=>{if(e.target===row&&(e.key==='Enter'||e.key===' ')){e.preventDefault();row.click()}}});bindActions($('vin-list'));bindMore($('vin-list'));if(drawerStep==='detail')renderDetail();else $('vin-detail').innerHTML=''};
renderDetail=function(){oldRenderDetail();const root=$('vin-detail');const c=getVIN(selectedVIN);if(!c)return;const rows=Array.from(root.querySelectorAll('.field-row'));if(rows.length){const grid=document.createElement('div');grid.className='detail-grid';rows[0].before(grid);rows.forEach(r=>grid.append(r))}const actions=root.querySelector('.detail-actions');if(actions){actions.innerHTML='<span class="helper">Thao tác trên VIN đang xem</span>'+actionHTML(c);bindActions(actions);bindMore(actions)}};
$('back-to-list').onclick=()=>{drawerStep='list';detailTab='specs';renderDrawer();$('drawer-search').focus();document.querySelector('.drawer-body').scrollTop=0};
document.addEventListener('click',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!e.target.closest('[data-more-vin]'))closeMore()});document.addEventListener('keydown',e=>{if(menu.hidden)return;const buttons=Array.from(menu.querySelectorAll('button'));const i=buttons.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeMore(true)}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:buttons.length-1))%buttons.length]?.focus()}else if(e.key==='Tab')closeMore()},true);document.querySelector('.drawer-body').addEventListener('scroll',()=>closeMore());window.addEventListener('resize',()=>closeMore());
document.querySelector('.demo-head p').textContent='Nhìn ảnh chọn dòng xe · Chọn VIN · Thao tác';document.querySelector('.demo-footer span').textContent='MẪU 22 · CHỌN XE GỌN, THAO TÁC THEO VIN';document.querySelector('.drawer-bottom span').textContent='Bấm VIN xem chi tiết · ⋯ cho thao tác phụ';
renderStock();
'''
html=base.replace('</style>',css+'</style>').replace('</body>','<script>'+js+'</script></body>')
html=html.replace('stock-preview-functional-v21','stock-preview-simplified-v22').replace('Kho xe · Mẫu 21 · Danh sách VIN đầy đủ','Kho xe · Mẫu 22 · Chọn xe tinh gọn')
(root/'public/previews/kho-xe-mau-22.html').write_text(html,encoding='utf-8')
print('Created simplified functional prototype 22')
